// Ventes → portail FKB2B. Accepte deux fichiers :
//  • l'export détaillé Fastmag (une ligne par article : LIGNE_BarCode, VENTE_nature…),
//    envoyé par le planificateur ;
//  • l'export Copilot VENTESTOCKFLOW (déjà agrégé).
// L'export Fastmag contient des données clients (nom, adresse…) : elles ne sortent jamais d'ici,
// seules référence / taille / magasin / jour / quantité / montant partent vers le portail.
// Envoi par tranches de 7 jours (chaque tranche remplace ses jours dans le portail).
const decoder = (octets) => {
  try { return new TextDecoder('utf-8', { fatal: true }).decode(octets); }
  catch (e) {
    try { return new TextDecoder('windows-1252').decode(octets); } catch (e2) { return octets.toString('latin1'); }
  }
};
const cellules = (ligne, sep) => {
  const res = []; let cour = '', entre = false;
  for (let i = 0; i < ligne.length; i++) {
    const ch = ligne[i];
    if (ch === '"') { if (entre && ligne[i + 1] === '"') { cour += '"'; i++; } else entre = !entre; }
    else if (ch === sep && !entre) { res.push(cour); cour = ''; }
    else cour += ch;
  }
  res.push(cour);
  return res;
};
const csv = (v) => '"' + String(v).replace(/"/g, '""') + '"';
const nombre = (v) => parseFloat(String(v || '0').replace(/\s/g, '').replace(',', '.')) || 0;

const sortie = [];
const items = $input.all();
for (let k = 0; k < items.length; k++) {
  const item = items[k];
  for (const cle of Object.keys(item.binary || {})) {
    const nomFichier = item.binary[cle].fileName || 'ventes.csv';
    if (!/\.(csv|txt|tsv)$/i.test(nomFichier)) continue;
    const texte = decoder(await this.helpers.getBinaryDataBuffer(k, cle)).replace(/^﻿/, '');
    const lignes = texte.split(/\r?\n/);
    const tete = lignes[0] || '';
    const sep = tete.includes('\t') ? '\t' : (tete.split(';').length > tete.split(',').length ? ';' : ',');
    const noms = cellules(tete, sep).map(x => x.trim());
    const col = (n) => noms.indexOf(n);

    // parJour[jour]['magasin|ref|taille'] = [quantité, montant]
    const parJour = {};
    const ajouter = (jourFr, magasin, ref, taille, q, mt) => {
      const m = /^(\d{2})\/(\d{2})\/(\d{4})/.exec(jourFr);
      if (!m || !ref || !magasin || !q) return;
      const jour = m[3] + '-' + m[2] + '-' + m[1];
      const bloc = parJour[jour] = parJour[jour] || {};
      const c = magasin + '|' + ref + '|' + taille;
      const e = bloc[c] = bloc[c] || [0, 0];
      e[0] += q; e[1] += mt;
    };

    if (col('LIGNE_BarCode') >= 0 && col('VENTE_nature') >= 0) {
      // export détaillé Fastmag : ventes + avoirs (retours), hors frais de port et mouvements de stock
      const iMag = col('LIGNE_CodeMag') >= 0 ? col('LIGNE_CodeMag') : col('VENTE_codemag');
      const iRef = col('LIGNE_BarCode'), iTaille = col('LIGNE_Taille'), iQ = col('LIGNE_Quantite'),
            iMt = col('LIGNE_Total'), iDate = col('VENTE_date'), iNat = col('VENTE_nature'), iFam = col('LIGNE_Famille');
      for (let i = 1; i < lignes.length; i++) {
        if (!lignes[i].trim()) continue;
        const c = cellules(lignes[i], sep);
        const nature = (c[iNat] || '').trim().toUpperCase();
        if (nature !== 'VENTE' && nature !== 'AVOIR') continue;
        const ref = (c[iRef] || '').trim();
        if (ref === 'FP' || ref === 'SHIPPING' || (c[iFam] || '').trim().startsWith('~')) continue;
        ajouter((c[iDate] || '').trim(), (c[iMag] || '').trim().toUpperCase(), ref,
                (c[iTaille] || '').trim(), Math.trunc(nombre(c[iQ])), nombre(c[iMt]));
      }
    } else if (col('BarCode V2') >= 0 && col('Jours dans Date') >= 0) {
      // export Copilot VENTESTOCKFLOW
      const iMt = col('Total MtVenteRetailTTC') >= 0 ? col('Total MtVenteRetailTTC') : col('MtVenteRetailTTC');
      const iQ = col('Total QteVenteRetail'), iTaille = col('Taille');
      const iJ = col('Jours dans Date'), iMag = col('Code_Origine'), iRef = col('BarCode V2');
      for (let i = 1; i < lignes.length; i++) {
        if (!lignes[i].trim()) continue;
        const c = cellules(lignes[i], sep);
        ajouter((c[iJ] || '').trim(), (c[iMag] || '').trim(), (c[iRef] || '').trim(),
                iTaille >= 0 ? (c[iTaille] || '').trim() : '', Math.trunc(nombre(c[iQ])), iMt >= 0 ? nombre(c[iMt]) : 0);
      }
    } else {
      continue; // pièce jointe qui n'est pas un fichier de ventes (état de stock…) : ignorée
    }

    const jours = Object.keys(parJour).sort();
    for (let i = 0; i < jours.length; i += 7) {
      const tranche = jours.slice(i, i + 7);
      let contenu = 'Code_Origine,BarCode V2,Taille,Jours dans Date,MtVenteRetailTTC,Total QteVenteRetail';
      let nb = 0;
      for (const jour of tranche) {
        const jourFr = jour.slice(8, 10) + '/' + jour.slice(5, 7) + '/' + jour.slice(0, 4);
        for (const [c, e] of Object.entries(parJour[jour])) {
          if (!e[0]) continue;
          const [magasin, ref, taille] = c.split('|');
          contenu += '\n' + [csv(magasin), csv(ref), csv(taille), csv(jourFr), e[1].toFixed(2), e[0]].join(',');
          nb++;
        }
      }
      if (!nb) continue;
      sortie.push({ json: {
        action: 'ventes_fastmag',
        fichier: nomFichier + ' (' + tranche[0] + ' → ' + tranche[tranche.length - 1] + ')',
        fichier_base64: Buffer.from(contenu, 'utf8').toString('base64'),
        encodage: 'utf-8'
      } });
    }
  }
}
// aucun fichier de ventes dans ce mail : on s'arrête sans erreur
return sortie;

// On n'écrit que si une tranche a coincé : un dépôt réussi reste silencieux.
const erreurs = $input.all().map(x => x.json);
return [{ json: {
  sujet: 'FKB2B ventes : ' + erreurs.length + ' tranche(s) non chargée(s)',
  texte: 'Le fichier VENTESTOCKFLOW est arrivé mais le portail a refusé une partie des ventes.\n\n' + JSON.stringify(erreurs, null, 2).slice(0, 4000)
} }];
